-- ============================================================================
-- SOURCE: supabase/migrations/0003_storage_setup.sql
-- ============================================================================

-- ============================================================================
-- Storage bucket for site images.
--
-- Run this AFTER 0002_rls_policies.sql (it depends on admin_users/is_admin()).
--
-- Bucket "site-images" is public-read (this is a public marketing site —
-- there's no reason to gate image loads behind signed URLs) and
-- admin-write only. Suggested folder layout inside the bucket, purely for
-- your own organization (Storage doesn't enforce folder structure) —
-- mirrors profile.js's existing image slots:
--   site-images/hero/
--   site-images/about/
--   site-images/case-studies/
--   site-images/gallery/
-- ============================================================================

-- file_size_limit / allowed_mime_types enforce the same limits as the
-- admin's client-side check (src/admin/content/supabaseStorage.js)
-- server-side too — the client check alone only stops an honest mistake,
-- not a direct API call with a valid admin session, so both layers exist
-- (Phase 2-G security pass).
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'site-images',
  'site-images',
  true,
  5242880, -- 5 MB, matches MAX_IMAGE_BYTES
  array['image/jpeg', 'image/png', 'image/webp', 'image/svg+xml'] -- matches ALLOWED_IMAGE_TYPES
)
on conflict (id) do update set
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

create policy "site_images_public_read"
  on storage.objects for select
  using (bucket_id = 'site-images');

create policy "site_images_admin_insert"
  on storage.objects for insert
  with check (bucket_id = 'site-images' and is_admin());

create policy "site_images_admin_update"
  on storage.objects for update
  using (bucket_id = 'site-images' and is_admin());

create policy "site_images_admin_delete"
  on storage.objects for delete
  using (bucket_id = 'site-images' and is_admin());


-- ============================================================================
-- SOURCE: supabase/migrations/0004_gallery_active_flag.sql
-- ============================================================================

-- ============================================================================
-- Phase 3-B — Gallery active/inactive flag
--
-- Lets an admin temporarily hide a gallery photo (e.g. a photo pending
-- replacement, or one that no longer fits) without deleting its row —
-- deleting also permanently removes the underlying Storage file and media
-- row, which isn't reversible. Adding a boolean flag instead makes hiding
-- a photo a safe, undoable action.
--
-- `default true` so every existing gallery_items row (and any inserted by
-- older client code that doesn't know about this column yet) stays visible
-- with no migration-time data change needed.
--
-- Admin-side only in this phase: src/admin/pages/images/GalleryImages.jsx
-- reads and writes this column, but the public site's gallery query
-- (src/lib/content/gallery.js) is intentionally left untouched — see
-- docs/PROJECT_STATUS.md's Phase 3-B entry for why, and Phase 3-C for the
-- planned follow-up.
-- ============================================================================

alter table gallery_items
  add column if not exists is_active boolean not null default true;


-- ============================================================================
-- SOURCE: supabase/migrations/0005_inquiries.sql
-- ============================================================================

-- ============================================================================
-- Phase 3-C — Business inquiries (Contact Form submissions)
--
-- A visitor-submitted table, unlike every other table in this schema
-- (which are all admin-authored site content). RLS here is the opposite
-- shape from 0002_rls_policies.sql's public-read/admin-write pattern:
-- anyone can INSERT (that's the whole point of a public contact form),
-- nobody but an admin can ever read, update, or delete a row.
--
-- `phone` is nullable and not currently collected by the public form
-- (src/components/ContactForm.jsx keeps only Name/Company/Email/Type of
-- Inquiry/Message, per this phase's explicit "don't add fields that
-- increase visitor input burden" instruction) — the column exists so a
-- future optional Phone field needs only a form change, not a migration.
-- ============================================================================

create table if not exists inquiries (
  id uuid primary key default gen_random_uuid(),
  name text not null check (length(name) between 1 and 200),
  company text check (company is null or length(company) <= 200),
  email text not null check (email ~* '^[^\s@]+@[^\s@]+\.[^\s@]+$' and length(email) <= 320),
  phone text check (phone is null or length(phone) <= 40),
  inquiry_type text not null check (length(inquiry_type) between 1 and 100),
  message text not null check (length(message) between 1 and 5000),
  status text not null default 'new' check (status in ('new', 'in_progress', 'completed')),
  created_at timestamptz not null default now()
);

create index if not exists inquiries_created_at_idx on inquiries (created_at desc);

alter table inquiries enable row level security;

-- Public: insert only, and only ever as a fresh 'new' inquiry — a direct
-- REST call can't plant a row that's already 'in_progress'/'completed'.
-- Column defaults (status, created_at, id) are applied before this check
-- runs, so a normal insert that omits `status` still satisfies it.
create policy "inquiries_public_insert" on inquiries
  for insert
  with check (status = 'new');

-- Admin: full read + status/management access. No public select/update/
-- delete policy exists at all, so those actions are unconditionally denied
-- to anyone who isn't in admin_users (RLS with no matching policy = deny).
create policy "inquiries_admin_select" on inquiries
  for select
  using (is_admin());

create policy "inquiries_admin_update" on inquiries
  for update
  using (is_admin())
  with check (is_admin());

create policy "inquiries_admin_delete" on inquiries
  for delete
  using (is_admin());


-- ============================================================================
-- SOURCE: supabase/migrations/0006_content_revisions.sql
-- ============================================================================

-- ============================================================================
-- Phase 3-G — Content revision history (minimal, not Git-like)
--
-- One generic table covers every admin-editable content table at once —
-- Hero, About/Profile, Impact, Case Studies, Advisory, Career, Contact,
-- and (as a side effect of being generic rather than per-table) Education
-- and Footer too. Before every admin save, the CURRENT row is snapshotted
-- here as jsonb; the actual write then proceeds normally. This is a
-- rolling "undo my last edit(s)" safety net, not a version-control
-- system: no branching, no diffing, no commit graph — just "what did this
-- row look like a moment ago, and can I put that back."
--
-- Deliberately excludes gallery_items/media (see 0007_gallery_soft_delete.sql
-- for that table's own, differently-shaped recovery mechanism) and
-- inquiries (visitor-submitted, not admin-authored content — Phase 3-C's
-- RLS already makes those effectively append-only from the public side).
-- ============================================================================

create table if not exists content_revisions (
  id uuid primary key default gen_random_uuid(),
  table_name text not null,
  row_id text not null, -- text so it fits both singleton tables (id=1) and uuid-keyed list tables
  snapshot jsonb not null,
  changed_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now()
);

create index if not exists content_revisions_lookup_idx
  on content_revisions (table_name, row_id, created_at desc);

alter table content_revisions enable row level security;

-- Same admin-only shape as every content table's write policy — nobody
-- but an admin session can ever read or write a revision. No update
-- policy at all: revisions are write-once from the client (append,
-- never edited). No client-facing delete policy either — pruning old
-- revisions happens only via the SECURITY DEFINER trigger below, which
-- bypasses RLS the same way is_admin() itself does.
create policy "content_revisions_admin_select" on content_revisions
  for select using (is_admin());

create policy "content_revisions_admin_insert" on content_revisions
  for insert with check (is_admin());

-- Retention cap — keeps at most the 10 most recent snapshots per
-- (table_name, row_id), so this table can't grow unbounded from repeated
-- edits over time. This is the one piece of "policy" here, and it's
-- intentionally simple: no configurable retention window, no archival
-- tier, just "keep the last 10, drop the rest."
create or replace function prune_content_revisions()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  delete from content_revisions
  where table_name = new.table_name
    and row_id = new.row_id
    and id not in (
      select id from content_revisions
      where table_name = new.table_name and row_id = new.row_id
      order by created_at desc
      limit 10
    );
  return new;
end;
$$;

drop trigger if exists content_revisions_prune on content_revisions;
create trigger content_revisions_prune
  after insert on content_revisions
  for each row execute function prune_content_revisions();


-- ============================================================================
-- SOURCE: supabase/migrations/0007_gallery_soft_delete.sql
-- ============================================================================

-- ============================================================================
-- Phase 3-G — Gallery soft delete
--
-- Deleting a gallery photo from the admin no longer immediately and
-- permanently removes its row (or the underlying media/storage file) —
-- it's marked `deleted_at`, disappears from both the public site and the
-- admin's main Gallery list, but can be restored from the admin's Trash
-- view. A separate, explicit "영구 삭제" (permanent delete) action is
-- still available in that Trash view for real cleanup — this migration
-- only changes what the everyday "삭제" action does.
--
-- The public read policy is tightened to match: a soft-deleted photo was
-- never meant to be visible again, unlike is_active
-- (0004_gallery_active_flag.sql), which is a temporary show/hide toggle.
-- src/lib/content/gallery.js additionally filters `deleted_at` client-side
-- as a second, independently-testable layer — see docs/PROJECT_STATUS.md's
-- Phase 3-G entry.
-- ============================================================================

alter table gallery_items
  add column if not exists deleted_at timestamptz;

drop policy if exists "gallery_items_public_read" on gallery_items;
create policy "gallery_items_public_read" on gallery_items
  for select using (deleted_at is null);

-- gallery_items_admin_write (`for all using (is_admin())`) already grants
-- the admin full select/insert/update/delete regardless of deleted_at —
-- unaffected by the policy above, which only replaces the *public* read
-- policy. No change needed there.


-- ============================================================================
-- SOURCE: supabase/migrations/0008_table_grants.sql
-- ============================================================================

-- ============================================================================
-- Production fix — missing PostgreSQL table GRANTs for anon/authenticated
--
-- 0002_rls_policies.sql enables RLS and defines correct policies on every
-- content table, but never grants the underlying SQL table privileges
-- themselves. RLS only *further restricts* rows on an operation a role
-- already has base privilege for — it never grants that base privilege.
-- Supabase normally auto-provisions this via a platform-level default
-- privilege bootstrap, but on this project's real Production database that
-- bootstrap did not cover these tables, so every read (even against a
-- `for select using (true)` public-read policy) failed with a literal
-- PostgreSQL ACL error: "permission denied for table hero_content" (and
-- identically for every other CMS table) — a privilege-layer rejection,
-- distinct from and prior to any RLS policy evaluation.
--
-- This migration records the exact fix already applied and verified
-- directly against the real Production project's SQL Editor, so a future
-- fresh project (via PRODUCTION_INITIAL_SETUP.sql or `supabase db push`)
-- doesn't hit the same gap. RLS policies remain the actual per-row access
-- control layer, unchanged — this only opens the base privilege RLS needs
-- to be evaluated at all.
-- ============================================================================

grant usage on schema public to anon, authenticated;

grant select on all tables in schema public to anon, authenticated;
grant insert, update, delete on all tables in schema public to authenticated;

alter default privileges in schema public
  grant select on tables to anon, authenticated;

alter default privileges in schema public
  grant insert, update, delete on tables to authenticated;


-- ============================================================================
-- SOURCE: supabase/migrations/0009_site_design_settings.sql
-- ============================================================================

-- ============================================================================
-- Phase 4-B — Site design settings (foundation for an admin-editable
-- Design System, built on top of Phase 4-A's CSS token layer)
--
-- Run this AFTER 0002_rls_policies.sql (is_admin()) and 0008_table_grants.sql.
--
-- Single-row "active design configuration" table, same id=1 singleton
-- shape as hero_content/about_content/etc. in 0001_init_schema.sql — one
-- config for the whole site, not per-section. Every column stores a
-- ready-to-use CSS value (a hex color, an rgba() string, a length like
-- "1280px", a plain unitless number) so a future runtime layer can apply
-- a row directly via `document.documentElement.style.setProperty('--x', v)`
-- with no per-field translation logic.
--
-- Defaults below are the exact literal values Phase 4-A's
-- src/styles/variables.css already resolves to today — connecting this
-- table to the site must not change how it looks. See
-- src/lib/content/designSettings.js for the read-side fallback that
-- guarantees the same thing if this table is ever missing/unreachable.
--
-- No admin UI reads or writes this table yet (Phase 4-B is data-layer
-- only) — src/lib/content/designSettings.js's fetch path is the only
-- consumer, and it isn't wired into page rendering yet either.
-- ============================================================================

create table if not exists site_design_settings (
  id integer primary key default 1 check (id = 1),

  -- Typography
  font_ko text not null,
  font_en text not null,
  body_font_size text not null,
  heading_scale numeric not null check (heading_scale > 0),
  line_height numeric not null check (line_height > 0),
  letter_spacing text not null,

  -- Colors
  color_primary text not null,
  color_secondary text not null,
  color_accent text not null,
  color_background text not null,
  color_surface text not null,
  color_text text not null,
  color_text_muted text not null,
  color_border text not null,

  -- Layout
  content_max_width text not null,
  section_spacing text not null,
  card_radius text not null,
  image_radius text not null,

  -- Motion
  motion_level text not null default 'standard'
    check (motion_level in ('minimal', 'standard', 'expressive')),
  image_motion_style text not null default 'none'
    check (image_motion_style in ('none', 'fade', 'zoom', 'parallax')),

  -- Metadata
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table site_design_settings enable row level security;

-- Same public-read/admin-write shape as every other content table
-- (0002_rls_policies.sql): anyone — signed out, signed in, or an admin —
-- can read the active design config (the public site needs it); only a
-- row in admin_users can insert/update it. No delete policy at all —
-- this singleton is never deleted, only ever updated in place.
create policy "site_design_settings_public_read" on site_design_settings
  for select using (true);
create policy "site_design_settings_admin_write" on site_design_settings
  for all using (is_admin()) with check (is_admin());

-- Explicit table GRANTs, not just the RLS policies above — 0008 already
-- grants these broadly across the whole public schema (including via
-- `alter default privileges` for tables created after it), but this
-- table is granted again here explicitly and unconditionally, so its
-- access never depends on exactly which role/session created it. This
-- is the same class of bug 0008 fixed ("permission denied for table X"
-- from a missing GRANT, independent of correct RLS policies) — belt and
-- suspenders, not a reaction to an observed failure this time.
grant select on site_design_settings to anon, authenticated;
grant insert, update, delete on site_design_settings to authenticated;

-- Seed the single active row with Phase 4-A's current literal values.
-- `on conflict do nothing` — if this ever re-runs after a real admin has
-- already customized the row, their values are never clobbered.
insert into site_design_settings (
  id,
  font_ko, font_en, body_font_size, heading_scale, line_height, letter_spacing,
  color_primary, color_secondary, color_accent, color_background, color_surface,
  color_text, color_text_muted, color_border,
  content_max_width, section_spacing, card_radius, image_radius,
  motion_level, image_motion_style
) values (
  1,
  '''Pretendard'', ''Noto Sans KR'', -apple-system, BlinkMacSystemFont, sans-serif',
  '''Inter'', ''Pretendard'', ''Noto Sans KR'', -apple-system, BlinkMacSystemFont, sans-serif',
  '1rem', 1.333, 1.75, 'normal',
  '#0b1625', '#f4f1ea', '#a4865c', '#f4f1ea', '#ffffff',
  '#222222', '#8b8984', 'rgba(34, 34, 34, 0.12)',
  '1280px', '6rem', '2px', '2px',
  'standard', 'none'
)
on conflict (id) do nothing;


-- ============================================================================
-- SOURCE: supabase/migrations/0010_storage_size_limit.sql
-- ============================================================================

-- ============================================================================
-- Phase 4-H — lower the site-images Storage bucket's file_size_limit to
-- match the tightened client-side MAX_IMAGE_BYTES
-- (src/admin/content/supabaseStorage.js).
--
-- Run this AFTER 0003_storage_setup.sql (which created the bucket).
--
-- 0003 already made this exact insert idempotent via `on conflict (id) do
-- update` — this migration doesn't edit that file (existing migrations
-- are never modified, only added to), it just re-runs the same upsert
-- with the new value, same as how 0008 added GRANTs and 0009 added a new
-- table rather than rewriting an earlier file.
--
-- 2 MB is still generous for a correctly-sized web photo (see
-- src/admin/content/imageGuidelines.js's recommended pixel dimensions —
-- the largest recommended slot is 1600x1200) — this only stops a
-- dramatically oversized/unoptimized upload, most importantly onto the
-- LCP-critical Hero slot. This is a validation-ceiling change only: it
-- does NOT touch, recompress, or delete any file already sitting in the
-- bucket — an existing upload larger than 2MB stays exactly as it is and
-- keeps being served normally; only a NEW upload is now checked against
-- the lower limit (both client-side and here, server-side).
-- ============================================================================

update storage.buckets
set file_size_limit = 2097152 -- 2 MB, matches MAX_IMAGE_BYTES
where id = 'site-images';


